import SkeletonService from '../../../../../src/services/SkeletonService';
import DataService from '../../../../../src/services/DataService';
import fs from 'fs';
import path from 'path';
const JobService = require('../../../../../services/JobService');

/**
 * FormCtrl - Laravel FormCtrl.php equivalent
 * Handles custom form submissions
 * Auto-generated by ModuleGenerator
 */

/**
 * Main API handler function
 * @param {Request} req 
 * @param {Response} res 
 * @returns {Promise<Response>}
 */
export default async function handler(req, res) {
    // Only allow POST requests
    if (req.method !== 'POST') {
      return res.status(405).json({
        status: false,
        title: 'Method Not Allowed',
        message: 'Only POST requests are allowed.'
      });
    }

    try {
      console.log('🎯 FormCtrl::handler() called');

      const token = req.body.save_token;
      
      if (!token) {
        return res.status(400).json({
      status: false,
          title: 'Token Missing',
          message: 'No token was provided.'
        });
      }

      // Resolve token
      const reqSet = await SkeletonService.resolveToken(token);
      
      if (!reqSet || !reqSet.status || !reqSet.key) {
        return res.status(400).json({
          status: false,
          title: 'Invalid Token',
          message: 'The provided token is invalid.'
    });
  }

      let reloadTable = true;
      let validated = {};
      let title = 'Success';
      let message = 'Data saved successfully.';

      // Handle different configuration keys
      switch (reqSet.key) {
        case 'central_querynest_insert':
          // Import CSV functionality - equivalent to bv project
          const { file, table, mapping, process_id, type, original_file_name } = req.body;
          
          // Validate required fields
          if (!file || !table || !mapping || !process_id || !type) {
            return res.status(422).json({
              status: false,
              title: 'Validation Error',
              message: 'Missing required fields: file, table, mapping, process_id, type'
            });
          }

          const filePath = path.join(process.cwd(), 'temp', 'imports', file);
          
          if (!fs.existsSync(filePath)) {
            return res.status(404).json({
              status: false,
              title: 'File Not Found',
              message: 'CSV file not found.'
            });
          }

          let parsedMapping;
          try {
            parsedMapping = typeof mapping === 'string' ? JSON.parse(mapping) : mapping;
          } catch (error) {
            return res.status(422).json({
              status: false,
              title: 'Invalid Mapping',
              message: 'Invalid mapping format.'
            });
          }

          // Normalize mapping shape for Import services.
          // Frontend (insert.js) & db-transfer use: { destinationField: sourceHeader }
          // ImportService / SimpleImportService expect: { sourceHeader: destinationField }.
          // To keep the UI stable and fix CSV imports, we invert the mapping here.
          const headerToFieldMapping = {};
          if (parsedMapping && typeof parsedMapping === 'object') {
            for (const [destField, sourceHeader] of Object.entries(parsedMapping)) {
              if (!sourceHeader) continue;
              headerToFieldMapping[sourceHeader] = destField;
            }
          }

          const [database, tableName] = table.split('.');
          const userId = req.user?.user_id || 1; // Get from auth

          // Try Bull Queue first, fallback to simple import if Redis not available
          let useSimpleImport = false;
          let importQueue;
          
          try {
            importQueue = require('../../../../../queues/importQueue');
            
            // Test if queue is ready
            await importQueue.isReady();
            console.log('✅ Using Bull Queue for import');
            
          } catch (queueError) {
            console.warn('⚠️ Bull Queue not available, using simple import:', queueError.message);
            useSimpleImport = true;
          }
          
          if (useSimpleImport) {
            // Use simple import service (no Redis required)
            try {
              const SimpleImportService = require('../../../../../services/SimpleImportService');
              
              const importService = new SimpleImportService({
                transferId: process_id,
                filePath,
                mappedColumns: headerToFieldMapping,
                database,
                table: tableName,
                type,
                userId,
                chunkSize: type === 'bulk' ? 10000 : 5000, // Optimized for faster imports
                originalFileName: original_file_name || file // Use original name or fallback to file param
              });

              // Process import synchronously (for small files) or asynchronously
              if (type === 'bulk') {
                // For bulk imports, process in background
                setImmediate(async () => {
                  try {
                    await importService.processImport();
                  } catch (error) {
                    console.error('❌ Simple import failed:', error.message);
                  }
                });
                
                return res.status(200).json({
                  status: true,
                  title: 'Processing',
                  message: 'Import started using simple processing (Redis not available).',
                  process_id,
                  mode: 'simple'
                });
              } else {
                // For normal imports, process immediately
                const result = await importService.processImport();
                
                return res.status(200).json({
                  status: true,
                  title: 'Completed',
                  message: 'Import completed successfully.',
                  process_id,
                  mode: 'simple',
                  result
                });
              }
              
            } catch (simpleError) {
              console.error('❌ Simple import failed:', simpleError.message);
              return res.status(500).json({
                status: false,
                title: 'Import Failed',
                message: 'Both Bull Queue and simple import failed. Please check the logs.',
                details: simpleError.message
              });
            }
          } else {
            // Use Bull Queue with Job Service logging (like BV project)
            try {
              const jobService = new JobService();
              
              // CRITICAL FIX: Create process_logs at QUEUE TIME (not worker time)
              // This ensures frontend can immediately see the job status as "pending"
              // Prevents SSE closing on "unknown" for sequential jobs
              await jobService.logProcessStart({
                process_id: process_id,
                user_id: userId,
                file: original_file_name || file,
                database,
                table: tableName,
                type
              });
              
              // Create job record (like Laravel dispatch)
              const jobRecord = await jobService.createJob({
                queue: 'high',
                data: {
                  transferId: process_id,
                  filePath,
                  mappedColumns: headerToFieldMapping,
                  database,
                  table: tableName,
                  type,
                  userId,
                  chunkSize: type === 'bulk' ? 10000 : 5000 // Optimized for faster imports
                }
              });

              // Add to Bull Queue (CSV Import Queue - highest priority)
              const job = await importQueue.add('csv-import', {
                transferId: process_id,
                filePath,
                mappedColumns: headerToFieldMapping,
                database,
                table: tableName,
                type,
                userId,
                chunkSize: type === 'bulk' ? 10000 : 5000, // Larger chunks for faster imports: 10k for bulk, 5k for normal
                originalFileName: original_file_name || file // Use original name or fallback to file param
              }, {
                priority: type === 'bulk' ? 10 : 5, // Higher priority than audience (3) and maintenance (1)
                attempts: 3,
                backoff: 'exponential',
                removeOnComplete: 10,
                removeOnFail: 50
              });

              await jobService.disconnect();

              console.log(`🚀 Import job queued: ${job.id} for transfer: ${process_id}`);

              return res.status(200).json({
                status: true,
                title: 'Queued',
                message: 'Import has started in the background using Bull Queue.',
                process_id,
                job_id: job.id,
                job_record_id: jobRecord.job_id,
                mode: 'bull_queue'
              });

            } catch (jobError) {
              console.error('❌ Failed to create import job:', jobError.message);
              return res.status(500).json({
                status: false,
                title: 'Job Creation Failed',
                message: 'Failed to create import job. Please try again.',
                details: jobError.message
              });
            }
          }
          break;

        case 'central_querynest':
         
          break;

        default:
          return res.status(400).json({
            status: false,
            title: 'Invalid Configuration',
            message: 'The configuration key is not supported.'
          });
      }

    return res.status(200).json({
      status: true,
        reload_table: reloadTable,
        token: reqSet.key,
        affected: '-',
        title: title,
        message: message
    });

  } catch (error) {
      console.error('❌ FormCtrl error:', error);
    return res.status(500).json({
      status: false,
        title: 'Error',
        message: error.message || 'An error occurred while saving the data.'
    });
    }
}
